import { estimateCost, decimalError, decimalUnits } from './costCalculator.js';
const $=s=>document.querySelector(s);const icon=n=>`<svg class="icon" aria-hidden="true"><use href="#${n}"/></svg>`;
const steps=['可售规格','参考素材','计费维度','填写单价','确认保存'];
const imageRows=[{key:'resolution:1K',label:'1K',price:'0.70',consumption:'8'},{key:'resolution:2K',label:'2K',price:'1.20',consumption:'10'},{key:'resolution:4K',label:'4K',price:'2.40',consumption:'18'}];
const videoRows=[{key:'resolution:720p,duration:5',label:'720p',price:'2.50',consumption:'18'},{key:'resolution:1080p,duration:5',label:'1080p',price:'4.00',consumption:'30'}];
const state={view:'editor',step:4,kind:'image',rows:imageRows,selected:0,opened:false,seen:new Set(),purchase:'100',credits:'1000',ref:'optional',res:['1K','2K','4K'],ratios:['1:1','16:9'],dims:['resolution'],lastTrigger:null};
const unit=()=>state.kind==='video'?'条':'张';const product=()=>state.kind==='video'?'视频创作 · 标准版':'GPT Image 2 标准版';
const model=()=>state.kind==='video'?'video-compatible-1':'gpt-image-2';
function display(value){if(value===undefined)return '待估算';if(value.includes('<'))return value;const neg=value.startsWith('−');const s=neg?value.slice(1):value;const pieces=s.split('.');return `${neg?'−':''}${pieces[0]}.${(pieces[1]||'').padEnd(2,'0')}`;}
function money(value){if(value===undefined)return '待估算';return value.startsWith('−')?'−¥'+display(value.slice(1)):'¥'+display(value);}
function calc(row){return estimateCost(state.purchase,state.credits,row.consumption,row.price===''?null:{amount:row.price,currency:'CNY',billing_mode:'per_request'});}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200);}
function showDialog(title,content){$('#dialog-title').textContent=title;$('#dialog-content').textContent=content;$('#dialog').showModal();}
function priceRows(){return `<div class="price-head"><span>规格组合</span><span>客户售价 · CNY / ${unit()}</span><span>上游成本参考</span></div>`+state.rows.map((r,i)=>`<div class="price-row" data-price-row="${i}"><div class="spec-info"><span class="spec-icon">${icon(state.kind==='video'?'media':'ratio')}</span><div><strong class="num">${r.label}</strong><p>${state.kind==='video'?'5 秒 · 每次 1 条':'1:1、16:9 同价'}</p></div></div><div class="price-input"><input class="sale" data-row="${i}" aria-label="${r.label} 客户售价" inputmode="decimal" value="${r.price}" placeholder="待填写"><span class="currency">¥</span><p class="error" data-price-error="${i}" role="status"></p></div><div class="cost-cell" data-cost-cell="${i}"></div></div>`).join('');}
function costCells(){state.rows.forEach((r,i)=>{const cell=$(`[data-cost-cell="${i}"]`);if(!cell)return;const e=calc(r);cell.innerHTML=state.seen.has(r.key)?`<div class="estimate"><span class="muted">估算成本</span><br><b class="num">${money(e.cost)}</b><span class="${e.belowCost?'loss':'muted'}" style="display:block;font-size:13px">${e.difference===undefined?'差额待估算':'差额 '+money(e.difference)}</span></div><button class="icon-btn" data-cost="${i}" aria-label="调整 ${r.label} 成本">${icon('calc')}</button>`:`<button class="mini-action" data-cost="${i}" aria-label="估算 ${r.label} 成本">${icon('calc')}估算成本</button>`;const row=$(`[data-price-row="${i}"]`);row.classList.toggle('is-selected',state.opened&&i===state.selected);});}
function stage(){if(state.step===4)return `<div class="section-heading"><div><h2>填写单价</h2><p>按${state.kind==='video'?'分辨率与时长':'分辨率'}定价，${state.rows.length} 个价格档位。</p></div><button class="subtle" id="open-cost" aria-label="打开成本换算">${icon('calc')}<span>成本换算</span></button></div><div class="price-table">${priceRows()}</div><p class="price-note">${icon('info')}空白为未配置，明确填 0 才是免费。图片按张，视频按整条。</p>`;
if(state.step===1)return `<div class="section-heading"><div><h2>选择可售规格</h2><p>只选择已确认支持、准备出售的规格。</p></div><span class="tag">${state.kind==='video'?'视频 · 单条':'图片 · 1–10 张'}</span></div><div class="field-group"><h3>分辨率</h3><div class="options">${(state.kind==='video'?['720p','1080p']:['1K','2K','4K']).map(x=>`<button class="chip chosen" data-spec="${x}" aria-pressed="true">${x}</button>`).join('')}</div></div><div class="field-group"><h3>宽高比例</h3><div class="options">${['1:1','16:9','9:16','4:3','3:4'].map(x=>`<button class="chip ${state.ratios.includes(x)?'chosen':''}" data-ratio="${x}" aria-pressed="${state.ratios.includes(x)}">${x}</button>`).join('')}</div></div><p class="feature-note">${state.kind==='video'?'视频固定生成一条。':'客户购买数量由系统管理，上游执行按已确认能力安排。'}<br>规格选择不改变 Account 的模型映射。</p>`;
if(state.step===2)return `<div class="section-heading"><div><h2>参考素材怎么提供？</h2><p>文生图和参考图编辑仍属于同一商品。</p></div></div><div class="choice-list">${[['none','不支持参考图','客户只需填写提示词。'],['optional','客户可选上传','不上传也能生成；上传后使用参考图编辑。'],['required','客户必须上传','没有参考图时，不允许提交。']].map(([v,t,d])=>`<button class="choice ${state.ref===v?'chosen':''}" data-reference="${v}" aria-pressed="${state.ref===v}"><span class="radio"></span><span><strong>${t}</strong><small>${d}</small></span></button>`).join('')}</div><p class="feature-note">数量限制沿用已确认接口能力与现有安全上限。</p>`;
if(state.step===3)return `<div class="section-heading"><div><h2>哪些规格影响单价？</h2><p>没选中的规格，客户仍可选择，但共享单价。</p></div></div><div class="dimension-grid">${[['resolution','分辨率','1K / 2K / 4K'],['ratio','宽高比例','1:1 / 16:9']].map(([v,t,d])=>`<button class="dimension-card ${state.dims.includes(v)?'chosen':''}" data-dimension="${v}" aria-pressed="${state.dims.includes(v)}"><span class="row between"><strong>${t}</strong><span class="check">${state.dims.includes(v)?'✓':''}</span></span><span>${d}</span><p>${state.dims.includes(v)?'每个选项分别填写单价':'不同选项共用一个单价'}</p></button>`).join('')}</div><p class="feature-note">现有价格会保留；变更计费维度时，先确认受影响的价格档位。</p>`;
return `<div class="section-heading"><div><h2>确认这份商品配置</h2><p>保存为草稿，由服务端检查后再单独发布。</p></div><span class="tag">${state.kind==='video'?'视频':'图片'}</span></div><div class="summary-line"><div><h3>商品名称</h3><p>当前上游模型：${model()}</p></div><div class="value">${product()}</div></div><div class="summary-line"><div><h3>可售规格</h3></div><div class="value">${state.rows.map(x=>x.label).join(' / ')}<p>${state.ratios.join(' / ')}</p></div></div><div class="summary-line"><h3>参考素材</h3><span>${{none:'不支持参考图',optional:'客户可选上传',required:'客户必须上传'}[state.ref]}</span></div><div class="summary-line"><h3>客户售价</h3><div class="value">${state.rows.map(x=>`${x.label} · ${x.price===''?'待填写':'¥'+x.price+' / '+unit()}`).join('<br>')}</div></div><p class="feature-note">保存范围为当前 Account 草稿。不会自动发布，不会开启销售。</p>`;}
function renderEditor(){return `<button class="text-btn" id="back-models">${icon('back')}返回模型列表</button><div class="context"><div><h1>${product()}</h1><p>Image2Pro 图片 / Account #77 <span style="margin:0 9px;color:var(--line)">|</span> ${model()}</p></div><div class="product-status row"><span class="tag green">草稿 · 已启用</span><button class="icon-btn" data-hint="商品启停与更多操作沿用现有确认流程" aria-label="更多商品操作">${icon('dots')}</button></div></div><nav class="stepper" aria-label="商品配置步骤">${steps.map((s,i)=>`<button data-step="${i+1}" class="${state.step===i+1?'current':i+1<state.step?'done':''}" ${state.step===i+1?'aria-current="step"':''}><span class="stepnum">${i+1<state.step?'✓':i+1}</span><span>${s}</span></button>`).join('')}<span class="indicator" style="transform:translateX(${(state.step-1)*100}%)"></span></nav><section class="stage" id="stage">${stage()}</section><footer class="footer"><button class="text-btn" id="prev" ${state.step===1?'disabled':''}>${icon('back')}上一步</button><div class="row"><span class="save-note"><span class="dirty-dot"></span>未保存修改</span><button class="primary" id="next">${state.step===5?'保存草稿':`下一步：${steps[state.step]}`} ${icon(state.step===5?'check':'arrow')}</button></div></footer>`;}
function renderModels(){return `<button class="text-btn" id="account-back">${icon('back')}来源与账号</button><div class="context model-heading"><div><h1>Image2Pro 图片</h1><p>Account #77 · 模型与商品</p></div><button class="outline" data-hint="账户详情沿用原页面">账户详情 ↗</button></div><div class="sales-line"><span class="tag">Account 销售已暂停</span><span>销售控制与发布配置分别管理</span><button class="text-btn" id="sales-info">管理销售状态</button></div><section class="pub-bar"><div><h3>发布此 Account 的配置</h3><p>包含账号全部草稿商品；发布不会自动开启销售。</p></div><button class="primary" id="publish-preview">发布配置 ${icon('arrow')}</button></section><div class="model-toolbar"><input id="model-search" type="search" aria-label="搜索模型" placeholder="搜索模型名称或精确 ID"><button class="outline filter" data-hint="可按原有模型状态筛选">全部状态 ${icon('chevron')}</button></div><div id="models">${[['image','gpt-image-2','GPT Image 2 标准版','1K / 2K / 4K','¥0.70 起 / 张'],['video','video-compatible-1','视频创作 · 标准版','720p / 1080p','¥2.50 起 / 条']].map(([kind,m,p,s,price])=>`<div class="model-row" data-model-name="${m} ${p}"><div><h3>${m}</h3><p>${p}</p></div><div class="spec">${s}<p>${price}</p></div><div class="model-status"><span class="tag green">草稿修改</span></div><button class="outline" data-model="${kind}">继续配置 ${icon('arrow')}</button></div>`).join('')}</div><p id="no-results" class="feature-note hidden">没有匹配的模型。</p><p class="feature-note">模型身份与映射来自当前 Account；商品独立配置可售规格与售价。</p>`;}
function render(){const scroll=window.scrollY;$('#main').innerHTML=state.view==='editor'?renderEditor():renderModels();costCells();if(state.opened)updateDrawer();window.scrollTo(0,Math.min(scroll,document.documentElement.scrollHeight));}
function goStep(n){if(n===state.step)return;closeCost(false);state.step=n;const indicator=$('.indicator');if(indicator)indicator.style.transform=`translateX(${(n-1)*100}%)`;document.querySelectorAll('[data-step]').forEach(el=>{const k=Number(el.dataset.step);el.className=k===n?'current':k<n?'done':'';if(k===n)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');el.querySelector('.stepnum').textContent=k<n?'✓':k;});$('#stage').innerHTML=stage();$('#stage').getAnimations().forEach(a=>a.cancel());$('#stage').animate([{opacity:0,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:matchMedia('(prefers-reduced-motion: reduce)').matches?0:200,easing:'ease-out'});$('#prev').disabled=n===1;$('#next').innerHTML=(n===5?'保存草稿':`下一步：${steps[n]}`)+' '+icon(n===5?'check':'arrow');costCells();}
function openCost(i,trigger){state.lastTrigger=trigger||$('#open-cost');state.selected=i;state.opened=true;state.seen.add(state.rows[i].key);$('#drawer').inert=false;$('#drawer').setAttribute('aria-hidden','false');$('#drawer').classList.add('open');document.body.classList.add('open-cost');updateDrawer();costCells();setDialogMode();$('#drawer-title').focus({preventScroll:true});}
function closeCost(focus=true){if(!state.opened)return;state.opened=false;document.body.classList.remove('open-cost');$('#drawer').classList.remove('open');$('#drawer').setAttribute('aria-hidden','true');$('#drawer').inert=true;$('.app').inert=false;$('.rail').inert=false;document.body.style.overflow='';costCells();if(focus&&state.lastTrigger?.isConnected)state.lastTrigger.focus({preventScroll:true});else if(focus)$('#open-cost')?.focus({preventScroll:true});}
function setDialogMode(){const modal=state.opened&&innerWidth<=1180;$('#drawer').setAttribute('role',modal?'dialog':'complementary');if(modal)$('#drawer').setAttribute('aria-modal','true');else $('#drawer').removeAttribute('aria-modal');$('.app').inert=modal;$('.rail').inert=modal;document.body.style.overflow=modal?'hidden':'';}
function updateDrawer(){const r=state.rows[state.selected];$('#drawer-context').textContent=product()+' · Account #77';$('#cost-tabs').style.gridTemplateColumns=`repeat(${state.rows.length},1fr)`;$('#cost-tabs').innerHTML=`<span class="seg-indicator" style="width:calc((100% - 8px)/${state.rows.length});transform:translateX(${state.selected*100}%)"></span>`+state.rows.map((r,i)=>`<button role="tab" aria-selected="${i===state.selected}" data-cost-tab="${i}" tabindex="${i===state.selected?0:-1}">${r.label}</button>`).join('');$('#cost-spec').textContent=r.label+' · 单'+unit()+'成本';$('#cost-unit').textContent=state.kind==='video'?'视频按整条':'图片按张';$('#purchase').value=state.purchase;$('#credits').value=state.credits;$('#consumption').value=r.consumption;updateResults();}
function updateResults(){const r=state.rows[state.selected],e=calc(r);$('#credit-rate').textContent=money(e.perCredit);$('#result-cost').textContent=money(e.cost);$('#result-sale').textContent=r.price!==''&&decimalUnits(r.price)!==undefined?'¥'+display(r.price):'待填写';$('#result-diff').textContent=money(e.difference);$('#result-diff').className=e.belowCost?'loss':'positive';$('#cost-alert').textContent=e.belowCost?'低于估算上游成本，请留意售价。':'';$('#cost-alert').classList.toggle('hidden',!e.belowCost);const err=decimalError(state.purchase,true)||decimalError(state.credits,true);$('#purchase-error').textContent=err;$('#consumption-error').textContent=decimalError(r.consumption);$('#purchase').setAttribute('aria-invalid',!!decimalError(state.purchase,true));$('#credits').setAttribute('aria-invalid',!!decimalError(state.credits,true));$('#consumption').setAttribute('aria-invalid',!!decimalError(r.consumption));costCells();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.hint){toast(b.dataset.hint);return;}if(b.hasAttribute('data-step'))goStep(Number(b.dataset.step));else if(b.hasAttribute('data-cost'))openCost(Number(b.dataset.cost),b);else if(b.hasAttribute('data-cost-tab')){state.selected=Number(b.dataset.costTab);state.seen.add(state.rows[state.selected].key);const idx=state.selected;const ind=$('.seg-indicator');ind.style.transform=`translateX(${idx*100}%)`;$('#cost-tabs').querySelectorAll('button').forEach((tab,i)=>{tab.setAttribute('aria-selected',i===idx);tab.tabIndex=i===idx?0:-1;});const r=state.rows[idx];$('#cost-spec').textContent=r.label+' · 单'+unit()+'成本';$('#consumption').value=r.consumption;updateResults();}else if(b.hasAttribute('data-model')){state.kind=b.dataset.model;state.rows=state.kind==='video'?videoRows:imageRows;state.view='editor';state.step=4;state.selected=0;render();window.scrollTo(0,0);}else if(b.hasAttribute('data-reference')){state.ref=b.dataset.reference;render();}else if(b.hasAttribute('data-ratio')){const x=b.dataset.ratio;state.ratios=state.ratios.includes(x)?state.ratios.filter(v=>v!==x):[...state.ratios,x];b.classList.toggle('chosen');b.setAttribute('aria-pressed',state.ratios.includes(x));}else if(b.hasAttribute('data-spec')){b.classList.toggle('chosen');b.setAttribute('aria-pressed',b.classList.contains('chosen'));}else if(b.hasAttribute('data-dimension')){showDialog('变更计费维度','正式界面会先说明受影响的价格并要求确认。本轮原型保留当前 3 档价格，不自动合并或覆盖已有单价。');}});
$('#main').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='open-cost')openCost(state.selected,b);if(b.id==='back-models'){closeCost(false);state.view='models';render();}if(b.id==='prev')goStep(state.step-1);if(b.id==='next'){if(state.step<5)goStep(state.step+1);else showDialog('保存草稿 · 操作预览','正式界面将在这里提交当前 Account 的草稿并等待服务端校验。本页为设计原型，没有保存任何商品，也没有连接生产。');}if(b.id==='publish-preview')showDialog('发布此 Account 的配置？','范围：Account #77 下的全部草稿商品，不限于当前搜索结果。正式界面仍需通过校验和二次确认。本页只展示确认层，不执行发布；发布配置不自动开启销售。');if(b.id==='sales-info')showDialog('Account 级销售控制','正式界面将列出受影响的已发布商品，单独确认开启或暂停销售。本页不会更改任何销售状态。');if(b.id==='account-back')showDialog('来源与账号','正式界面保留 Account ID、名称、域名和平台搜索。本轮交互重点是商品编辑和成本抽屉。');});
$('#main').addEventListener('input',e=>{if(e.target.matches('.sale')){const i=Number(e.target.dataset.row);state.rows[i].price=e.target.value;$(`[data-price-error="${i}"]`).textContent=decimalError(e.target.value);e.target.setAttribute('aria-invalid',!!decimalError(e.target.value));costCells();if(state.opened)updateResults();}if(e.target.id==='model-search'){let count=0;document.querySelectorAll('[data-model-name]').forEach(row=>{const visible=row.dataset.modelName.toLowerCase().includes(e.target.value.toLowerCase());row.classList.toggle('hidden',!visible);if(visible)count++;});$('#no-results').classList.toggle('hidden',count!==0);}});
$('#purchase').addEventListener('input',e=>{state.purchase=e.target.value;updateResults();});$('#credits').addEventListener('input',e=>{state.credits=e.target.value;updateResults();});$('#consumption').addEventListener('input',e=>{state.rows[state.selected].consumption=e.target.value;updateResults();});
$('#close-cost').onclick=()=>closeCost();$('#drawer-mask').onclick=()=>closeCost();$('#dialog-close').onclick=()=>$('#dialog').close();
function theme(){const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';$('#theme').setAttribute('aria-label',dark?'切换浅色模式':'切换深色模式');}$('#theme').onclick=theme;$('#theme-top').onclick=theme;$('#rail-media').onclick=()=>{closeCost(false);state.view='models';render();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.opened&&!$('#dialog').open){e.preventDefault();closeCost();}if(state.opened&&e.key==='Tab'&&innerWidth<=1180){const els=[...$('#drawer').querySelectorAll('button,input,summary,[tabindex="0"]')].filter(x=>x.offsetParent!==null&&!x.disabled);const first=els[0],last=els.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('#drawer-title'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if(e.target.matches('[data-cost-tab]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const i=(state.selected+(e.key==='ArrowRight'?1:-1)+state.rows.length)%state.rows.length;$(`[data-cost-tab="${i}"]`).click();$(`[data-cost-tab="${i}"]`).focus();}});
window.addEventListener('resize',()=>state.opened&&setDialogMode());
if(new URLSearchParams(location.search).get('theme')==='dark')document.documentElement.dataset.theme='dark';render();
